Here's how to handle each scenario with modern MSTest (3.9+):

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class MixedEnvironmentTests : IDisposable
{
    private string? _tempFile;

    // 1. Windows-only (registry access)
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void Registry_ReadsExpectedValue()
    {
        var value = Registry.GetValue(@"HKEY_LOCAL_MACHINE\SOFTWARE\...", "Key", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI (requires local GPU)
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void GpuRender_ProducesValidFrame()
    {
        var frame = GpuRenderer.RenderFrame();
        Assert.IsNotNull(frame);
    }

    // 3. Flaky external API — retry up to 3 times
    [TestMethod]
    [Retry(3)]
    public async Task WeatherApi_ReturnsForecast()
    {
        var forecast = await WeatherClient.GetForecastAsync();
        Assert.IsNotEmpty(forecast.Days);
    }

    // 4. Cleanup temp files even on failure
    [TestMethod]
    public void Export_WritesToTempFile()
    {
        _tempFile = Path.GetTempFileName();
        Exporter.WriteData(_tempFile);
        Assert.IsTrue(File.Exists(_tempFile));
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFile is not null && File.Exists(_tempFile))
        {
            File.Delete(_tempFile);
        }
    }

    public void Dispose() => Cleanup();
}
```

**Key attributes:**

| Scenario | Attribute | Behavior |
|----------|-----------|----------|
| Windows-only | `[OSCondition(OperatingSystems.Windows)]` | Skipped on Linux/macOS |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` | Skipped when CI env detected |
| Flaky API | `[Retry(3)]` | Re-runs up to 3 times on failure |
| Temp file cleanup | `[TestCleanup]` | Runs after every test, even on failure |

**Notes:**
- `[TestCleanup]` always runs post-test (pass or fail) — ideal for resource cleanup.
- `[Retry]` (MSTest 3.9+) should only be used for genuinely flaky external dependencies, not to mask race conditions.
- `[OSCondition]` (3.10+) and `[CICondition]` (3.10+) replace manual `if (RuntimeInformation...)` guards and report the test as "skipped" rather than silently passing.
